#include <cstdint>
#include <iostream>
#include <limits>
int main() {
    const unsigned payload = 250, header = 10;
    const auto narrowed = static_cast<std::uint8_t>(payload + header);
    const unsigned maximum = std::numeric_limits<std::uint8_t>::max();
    const bool allowed = header <= maximum && payload <= maximum - header;
    std::cout << "wrapped-total=" << unsigned(narrowed) << '\n';
    std::cout << "checked=" << (allowed ? "accept" : "reject") << '\n';
    // No allocation or out-of-bounds copy is attempted.
}

#include <iostream>
#include <memory>
#include <string>
int main() {
    std::weak_ptr<std::string> observer;
    {
        auto owner = std::make_shared<std::string>("ready");
        observer = owner;
        std::cout << "alive=" << !observer.expired() << '\n';
    } // The only strong owner ends; the string is destroyed.
    std::cout << "expired=" << observer.expired() << '\n';
    if (auto owner = observer.lock()) std::cout << *owner << '\n';
    else std::cout << "unavailable\n";
}
